// The `sharp` shape: ONE declaration file, an ambient dependency on node's
// types, and a full API surface of its own.
/// <reference types="node" />

/**
 * Block comments and jsdoc must not be counted as declarations.
 */
declare function ambient(input?: Buffer): Ambient

interface Ambient {
    resize(width?: number, height?: number): Ambient
    webp(options?: {quality?: number}): Ambient
    rotate(angle?: number): Ambient
}

declare namespace ambient {
    type Metadata = {width: number; height: number}
}

export = ambient
